# Retry exact tiling: place the 7 non-singleton tiles and leave any 2 cells for the two color-4 singleton pixels.
solutions=[]; nodes=0

def solve2(rem, used, singles_left, placed, maxsol=20):
    global nodes
    nodes+=1
    if len(solutions)>=maxsol:return
    if used==(1<<7)-1:
        if rem.bit_count()==singles_left:
            solutions.append((placed, [i for i in range(len(coords)) if (rem>>i)&1]))
        return
    # choose cell with smallest number of candidate non-single placements, but must allow it remain single
    bestopts=None; bestcell=None
    bits=rem
    while bits:
        b=bits & -bits; ci=b.bit_length()-1; bits-=b
        opts=[]
        for pi in range(7):
            if used>>pi & 1: continue
            if pi==2 and not (used>>1 & 1): continue
            for bm in all_candidates[pi]:
                if bm & b and (bm & rem)==bm:
                    opts.append((pi,bm))
        if bestopts is None or len(opts)<len(bestopts):
            bestopts=opts;bestcell=ci
            if len(opts)==0:break
    # if there are no options, this cell has to be one of singles
    if not bestopts:
        if singles_left:
            solve2(rem & ~(1<<bestcell), used, singles_left-1, placed, maxsol)
        return
    for pi,bm in bestopts:
        solve2(rem^bm, used|(1<<pi), singles_left, placed+[(pi,bm)],maxsol)
        if len(solutions)>=maxsol:return
    # optional skip a covered-able cell as singleton; but pruning by most constrained and count sizes may be helpful
    if singles_left:
